SELECT review_id, target_type, target_id, author_id, review_round, action, source, operator_id,
       reason, reason_code, create_time, update_time
FROM content_review
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
ORDER BY review_round ASC, id ASC

SELECT review_id, target_type, target_id, author_id, review_round, action, source, operator_id,
       reason, reason_code, create_time, update_time
FROM content_review
WHERE author_id = #{authorId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, target_id AS targetId, reason
FROM content_review
WHERE target_type = #{targetType}
  AND action = 'REJECT'
  AND target_id IN

      #{id}
